inline bool original_glyph_reference_matches_bgra(std::span<const std::uint8_t> source, std::uint32_t frame)
{
    const auto expected = original_glyph_coverage_pixels(frame);
    if (expected.size() != 64U * 64U * 4U || source.size() != expected.size()) return false;
    for (std::size_t i = 0U; i < source.size(); i += 4U)
        if (source[i] != expected[i + 2U] || source[i + 1U] != expected[i + 1U] ||
            source[i + 2U] != expected[i] || source[i + 3U] != expected[i + 3U]) return false;
    return true;
}
